cli.cjs.content:
const { formatStatus } = require('./format.cjs');
const [status, title, ...extra] = process.argv.slice(2);
if (status === undefined || title === undefined || extra.length) {
  process.stderr.write('usage: node cli.cjs STATUS TITLE\n');
  process.exitCode = 2;
} else {
  process.stdout.write(formatStatus(status, title) + '\n');
}

format.cjs.content:
const prefixes = new Map([
  ['queued', '[WAIT] '],
  ['active', '[RUN] '],
  ['paused', '[HOLD] '],
  ['done', '[OK] '],
  ['failed', '[FAIL] '],
  ['cancelled', '[STOP] '],
]);

function formatStatus(status, title) {
  const prefix = prefixes.get(status) ?? '[?] ';
  return prefix + title;
}
module.exports = { formatStatus };

format.test.cjs.content:
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const { formatStatus } = require('./format.cjs');
const formatRows = require('./consumer.cjs');

test('formats every exact status and preserves title bytes', () => {
  assert.deepEqual([
    formatStatus('queued', 'Build'),
    formatStatus('active', 'Build'),
    formatStatus('paused', 'Build'),
    formatStatus('done', 'Build'),
    formatStatus('failed', 'Build'),
    formatStatus('cancelled', 'Build'),
    formatStatus('done', ''),
    formatStatus('active', '  café\nnext\t'),
  ], ['[WAIT] Build', '[RUN] Build', '[HOLD] Build', '[OK] Build',
    '[FAIL] Build', '[STOP] Build', '[OK] ', '[RUN]   café\nnext\t']);
});

test('unknown statuses use the fallback without coercing status', () => {
  const statuses = ['unknown', 'Queued', ' queued', 'done ', '', 'constructor',
    'toString', '__proto__', undefined, null, 0, false, NaN, 1n,
    Symbol('queued'), new String('queued'), ['queued'],
    { [Symbol.toPrimitive]() { throw new Error('status was coerced'); } }];
  for (const status of statuses) assert.equal(formatStatus(status, 'Build'), '[?] Build');
});

test('title conversion retains addition semantics and propagates errors', () => {
  assert.equal(formatStatus(), '[?] undefined');
  assert.equal(formatStatus('done', null), '[OK] null');
  assert.equal(formatStatus('done', 42), '[OK] 42');
  assert.equal(formatStatus('done', false), '[OK] false');
  assert.equal(formatStatus('done', 12n), '[OK] 12');
  assert.equal(formatStatus('done', ['a', 'b']), '[OK] a,b');
  assert.equal(formatStatus('done', {
    [Symbol.toPrimitive](hint) { assert.equal(hint, 'default'); return 'default title'; },
  }), '[OK] default title');
  assert.throws(() => formatStatus('done', Symbol('title')), TypeError);
  const error = new Error('title conversion failed');
  assert.throws(() => formatStatus('done', {
    [Symbol.toPrimitive]() { throw error; },
  }), value => value === error);
});

test('keeps the public export and row consumer contract', () => {
  assert.deepEqual(Object.keys(require('./format.cjs')), ['formatStatus']);
  assert.equal(formatStatus.length, 2);
  assert.deepEqual(formatRows([
    { status: 'active', title: 'First' },
    { status: 'done', title: 'Second' },
    { status: 'Done', title: 'Third' },
    {},
  ]), ['[RUN] First', '[OK] Second', '[?] Third', '[?] undefined']);
  const rows = [{ status: 'queued', title: 'First' }, , { status: 'failed', title: 'Last' }];
  assert.deepEqual(formatRows(rows), ['[WAIT] First', , '[FAIL] Last']);
  assert.throws(() => formatRows([null]), TypeError);
});

test('CLI preserves exact stdout and accepts empty strings', () => {
  for (const [args, expected] of [
    [['queued', 'Build'], '[WAIT] Build\n'],
    [['active', 'Build'], '[RUN] Build\n'],
    [['paused', 'Build'], '[HOLD] Build\n'],
    [['done', 'Build'], '[OK] Build\n'],
    [['failed', 'Build'], '[FAIL] Build\n'],
    [['cancelled', 'Build'], '[STOP] Build\n'],
    [['Done', 'Build'], '[?] Build\n'],
    [['__proto__', 'Build'], '[?] Build\n'],
    [['', ''], '[?] \n'],
    [['active', '  café\nnext\t'], '[RUN]   café\nnext\t\n'],
  ]) {
    const result = spawnSync(process.execPath, [require.resolve('./cli.cjs'), ...args], { encoding: 'utf8' });
    assert.equal(result.status, 0);
    assert.equal(result.signal, null);
    assert.equal(result.stdout, expected);
    assert.equal(result.stderr, '');
  }
});

test('CLI preserves usage errors and exit code', () => {
  for (const args of [[], ['done'], ['done', 'Build', 'extra']]) {
    const result = spawnSync(process.execPath, [require.resolve('./cli.cjs'), ...args], { encoding: 'utf8' });
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.equal(result.stderr, 'usage: node cli.cjs STATUS TITLE\n');
  }
});

