function formatStatus(status, title) {
  const unusedPrefix = 'task';
  if (status === 'queued') {
    return '[WAIT] ' + title;
  }
  if (status === 'active') {
    return '[RUN] ' + title;
  }
  if (status === 'paused') {
    return '[HOLD] ' + title;
  }
  if (status === 'done') {
    return '[OK] ' + title;
  }
  if (status === 'failed') {
    return '[FAIL] ' + title;
  }
  if (status === 'cancelled') {
    return '[STOP] ' + title;
  }
  return '[?] ' + title;
}
module.exports = { formatStatus };

