jstack-refactoring-history.py.content:
from pathlib import Path
import tempfile,subprocess,json,hashlib,sys
root=Path('/tmp/jstack-refactoring-20261016');two='--two-seat' in sys.argv;app=root/('two-seat-app' if two else 'app');out=root/('two-seat-parent' if two else 'parent')
baseline=json.loads((out/'baseline.json').read_text());base=baseline['base']
def git(*args):return subprocess.check_output(['git',*args],cwd=app,text=True)
commits=git('rev-list','--reverse',base+'..HEAD').splitlines();records=[]
for commit in commits:
 with tempfile.TemporaryDirectory(prefix='jstack-refactor-replay-')as temp:
  temp=Path(temp)
  for name in git('ls-tree','-r','--name-only',commit).splitlines():
   p=temp/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(subprocess.check_output(['git','show',commit+':'+name],cwd=app))
  t=subprocess.run(['node','--test'],cwd=temp,text=True,capture_output=True);fail=[];proof=[]
  for old in baseline['cases']:
   p=subprocess.run(['node','cli.cjs',*old['args']],cwd=temp,text=True,capture_output=True);actual={'exit':p.returncode,'stdout':p.stdout,'stderr':p.stderr};proof.append(actual)
   if any(actual[k]!=old[k]for k in actual):fail.append({'args':old['args'],'actual':actual,'expected':old})
  records.append({'commit':commit,'subject':git('show','-s','--format=%s',commit).strip(),'test':{'argv':['node','--test'],'exit':t.returncode,'stdout':t.stdout,'stderr':t.stderr},'publicCases':len(proof),'failures':fail,'resultsSHA256':hashlib.sha256(json.dumps(proof,sort_keys=True).encode()).hexdigest()})
(out/'history-verification.json').write_text(json.dumps(records,indent=2)+'\n')
print(json.dumps([{'commit':r['commit'],'subject':r['subject'],'testExit':r['test']['exit'],'cases':r['publicCases'],'failures':len(r['failures'])}for r in records],indent=2))
assert all(r['test']['exit']==0 and not r['failures']for r in records)
if not records:print('No local delivery commits exist; history replay is not applicable. Uncommitted delivery requires separate final-artifact verification.')

