r={'scratch':str(scratch),'base':base,'finalHead':git('rev-parse','HEAD').strip(),'history':git('log','--reverse','--format=fuller','--stat'),'diff':git('diff',base),'finalFiles':files,'status':git('status','--short'),'rawArtifacts':artifacts,'indexedSourceReadsAndCatalogs':indexed,'scripts':scripts,'limits':'Artifact archive is not a full transcript. Large successful source-reading outputs and full capability catalogs are indexed by hash, not embedded; structured command records retain their argv, stderr and status. Raw runtime outputs and evaluator failures are retained where captured.'}
